const ZadFeedback=(()=>{"use strict";let toastTimer=null;function toast(msg,type="info",duration=2600){let el=document.getElementById("zad-toast");if(!el){el=document.createElement("div");el.id="zad-toast";el.setAttribute("role","status");el.setAttribute("aria-live","polite");document.body.appendChild(el)}const icons={info:"ℹ️",success:"✅",error:"⚠️",warn:"🔔"};el.innerHTML=`<span class="zt-icon">${icons[type]||""}</span><span>${msg}</span>`;el.className=`zad-toast zt-${type} show`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove("show"),duration);try{if(navigator.vibrate&&navigator.userActivation?.hasBeenActive){if(type==="success")navigator.vibrate(20);else if(type==="error")navigator.vibrate([30,20,30])}}catch{}}function showLoading(msg="جارٍ التحميل..."){let el=document.getElementById("zad-loading");if(!el){el=document.createElement("div");el.id="zad-loading";el.className="zad-loading";el.innerHTML=`<div class="zl-box"><div class="zl-spinner"></div><div class="zl-msg"></div></div>`;document.body.appendChild(el)}el.querySelector(".zl-msg").textContent=msg;el.classList.add("show")}function hideLoading(){document.getElementById("zad-loading")?.classList.remove("show")}function skeleton(container,count=3){if(typeof container==="string")container=document.getElementById(container);if(!container)return;container.innerHTML=Array.from({length:count},()=>`<div class="zad-skel-card">\n        <div class="zad-skel zad-skel-line" style="width:60%"></div>\n        <div class="zad-skel zad-skel-line" style="width:90%"></div>\n        <div class="zad-skel zad-skel-line" style="width:75%"></div>\n      </div>`).join("")}function successPulse(element){if(!element)return;element.classList.add("zad-success-pulse");setTimeout(()=>element.classList.remove("zad-success-pulse"),600);if(navigator.vibrate)navigator.vibrate([20,30,40])}function buttonLoading(btn,loading=true){if(typeof btn==="string")btn=document.getElementById(btn);if(!btn)return;if(loading){btn.dataset.origText=btn.innerHTML;btn.disabled=true;btn.innerHTML='<span class="zad-btn-spinner"></span>'}else{btn.disabled=false;if(btn.dataset.origText)btn.innerHTML=btn.dataset.origText}}function injectCSS(){if(document.getElementById("zad-feedback-css"))return;const s=document.createElement("style");s.id="zad-feedback-css";s.textContent=`\n      /* Toast */\n      .zad-toast {\n        position: fixed; bottom: 92px; left: 50%; transform: translateX(-50%) translateY(20px);\n        background: var(--ink,#1a1a18); color: #fff; padding: 12px 20px;\n        border-radius: var(--r-full,9999px); font-size: 14px; font-weight: 700;\n        display: flex; align-items: center; gap: 8px; z-index: 9900;\n        box-shadow: 0 8px 28px rgba(0,0,0,.3); opacity: 0; pointer-events: none;\n        max-width: calc(100vw - 32px); transition: opacity .3s, transform .3s;\n      }\n      .zad-toast.show { opacity: 1; transform: translateX(-50%) translateY(0); }\n      .zad-toast.zt-success { background: var(--green-mid,#1a5d47); }\n      .zad-toast.zt-error { background: #b3261e; }\n      @media (max-width: 768px) { .zad-toast { bottom: 140px; } }\n\n      /* Loading overlay */\n      .zad-loading {\n        position: fixed; inset: 0; z-index: 9950; display: flex;\n        align-items: center; justify-content: center; background: rgba(0,0,0,.4);\n        opacity: 0; pointer-events: none; transition: opacity .25s;\n      }\n      .zad-loading.show { opacity: 1; pointer-events: auto; }\n      .zl-box { background: var(--card,#fff); border-radius: 16px; padding: 24px 32px;\n        display: flex; flex-direction: column; align-items: center; gap: 14px; }\n      .zl-spinner { width: 36px; height: 36px; border: 3px solid var(--border,#eee);\n        border-top-color: var(--green-deep,#0e3b2e); border-radius: 50%;\n        animation: zad-spin .7s linear infinite; }\n      .zl-msg { font-size: 14px; font-weight: 700; color: var(--ink,#222); }\n      @keyframes zad-spin { to { transform: rotate(360deg); } }\n\n      /* Skeleton */\n      .zad-skel-card { background: var(--card,#fff); border-radius: 12px;\n        padding: 16px; margin-bottom: 10px; border: 1px solid var(--border,#eee); }\n      .zad-skel { background: linear-gradient(90deg, var(--border,#eee) 25%,\n        var(--sand,#f5f5f0) 50%, var(--border,#eee) 75%);\n        background-size: 200% 100%; animation: zad-shimmer 1.4s infinite; border-radius: 6px; }\n      .zad-skel-line { height: 14px; margin-bottom: 8px; }\n      @keyframes zad-shimmer { 0%{background-position:200% 0} 100%{background-position:-200% 0} }\n\n      /* Button spinner */\n      .zad-btn-spinner { display: inline-block; width: 16px; height: 16px;\n        border: 2px solid rgba(255,255,255,.4); border-top-color: #fff;\n        border-radius: 50%; animation: zad-spin .6s linear infinite; }\n\n      /* Success pulse */\n      .zad-success-pulse { animation: zad-pulse .6s var(--ease-spring,ease); }\n      @keyframes zad-pulse { 0%{transform:scale(1)} 40%{transform:scale(1.08)} 100%{transform:scale(1)} }\n\n      @media (prefers-reduced-motion: reduce) {\n        .zad-toast, .zad-loading, .zl-spinner, .zad-skel, .zad-btn-spinner, .zad-success-pulse {\n          animation: none !important; transition: opacity .15s !important;\n        }\n      }\n    `;document.head.appendChild(s)}function init(){injectCSS();const oldToast=window.showToast;window.showToast=(msg,type)=>{if(!type){if(/✅|تم|نجح/.test(msg))type="success";else if(/⚠️|خطأ|فشل|تعذّر/.test(msg))type="error";else type="info"}toast(msg,type)}}return{init:init,toast:toast,showLoading:showLoading,hideLoading:hideLoading,skeleton:skeleton,successPulse:successPulse,buttonLoading:buttonLoading}})();window.ZadFeedback=ZadFeedback;document.addEventListener("DOMContentLoaded",()=>ZadFeedback.init());